static
int
_str_equal(const uchar *a_,
           const char  *b_)
{
  while(*a_ && *b_)
    {
      if(*a_ != (uchar) * b_)
        return 0;
      a_++;
      b_++;
    }
  return *a_ == 0 && *b_ == 0;
}


static
void
_copy_name(uchar       *dst_,
           const uchar *src_,
           int32        max_)
{
  int32 i;

  if(!dst_ || max_ <= 0)
    return;
  i = 0;
  while(src_ && src_[i] && i < max_ - 1)
    {
      dst_[i] = src_[i];
      i++;
    }
  dst_[i] = 0;
}


static
void
_set_option(uint8      *Option_,
            const char *name_)
{
  _copy_name(Option_, (const uchar *)name_, 15);
}


static
void
_set_option_adjust(uint8      *Option_,
                   const char *name_,
                   int32       delta_)
{
  _set_option(Option_, name_);
  point += delta_;
}


static
int32
_back_pic_size(ScreenContext *sc_)
{
  if(sc_ && sc_->sc_nFrameBufferPages > 0 && GrafBase)
    {
      return sc_->sc_nFrameBufferPages * GrafBase->gf_VRAMPageSize;
    }
  return BULLETHOLE_SCREEN_W * BULLETHOLE_SCREEN_H * 2;
}


static
int32
_current_screen(ScreenContext *sc_)
{
  int32 screen;

  if(!sc_)
    return 0;
  screen = sc_->sc_curScreen;
  if(screen < 0 || screen >= 6)
    return 0;
  return screen;
}


static
void
_set_quad(Point quad[4],
          Coord left_,
          Coord top_,
          Coord right_,
          Coord bottom_)
{
  quad[0].pt_X = left_;
  quad[0].pt_Y = top_;
  quad[1].pt_X = right_;
  quad[1].pt_Y = top_;
  quad[2].pt_X = right_;
  quad[2].pt_Y = bottom_;
  quad[3].pt_X = left_;
  quad[3].pt_Y = bottom_;
}


static
void
_center_cel(CCB *cel_)
{
  Point quad[4];
  Coord left;
  Coord top;

  if(!cel_)
    return;
  left = (BULLETHOLE_SCREEN_W - cel_->ccb_Width) / 2;
  top  = (BULLETHOLE_SCREEN_H - cel_->ccb_Height) / 2;
  _set_quad(quad, left, top, left + cel_->ccb_Width, top + cel_->ccb_Height);
  MapCel(cel_, quad);
}


Boolean
InitBackPic(ScreenContext *sc_,
            Item           VRAMIOReq_)
{
  int32 size;
  uint32 memType;
  Err err;

  if(!sc_ || VRAMIOReq_ <= 0)
    return 0;
  if(!GrafBase)
    return 0;
  size    = _back_pic_size(sc_);
  memType = GETBANKBITS(GrafBase->gf_ZeroPage) | BACKPIC_MEMTYPE;
  gBackPic = (ubyte *)AllocMem(size, memType);
  if(!gBackPic)
    return 0;
  err = SetVRAMPages(VRAMIOReq_, gBackPic, 0, sc_->sc_nFrameBufferPages, -1);
  if(err < 0)
    {
      FreeMem(gBackPic, size);
      gBackPic = 0;
      return 0;
    }
  return 1;
}


int32
CopyBackPic(ScreenContext *TheScreen_,
            Bitmap        *bitmap_,
            Item           VRAMIOReq_)
{
  if(TheScreen_ == NULL || bitmap_ == NULL || gBackPic == NULL)
    {
      return -1;
    }

  return CopyVRAMPages(
    VRAMIOReq_,
    bitmap_->bm_Buffer,
    gBackPic,
    TheScreen_->sc_nFrameBufferPages,
    (uint32) - 1);
}


Boolean
InitPicture(ScreenContext *TheScreen_)
{
  Item vramIOReq;
  Err err;
  int32 screen;
  Bitmap *bitmap;

  if(!TheScreen_)
    return 0;
  vramIOReq = GetVRAMIOReq();
  if(vramIOReq < 0)
    return 0;

  screen = _current_screen(TheScreen_);
  bitmap = TheScreen_->sc_Bitmaps[screen];
  if(bitmap)
    {
      err = SetVRAMPages(vramIOReq, bitmap->bm_Buffer, 0, TheScreen_->sc_nFrameBufferPages, -1);
      if(err < 0)
        {
          DeleteItem(vramIOReq);
          return 0;
        }
    }

  TheScreen_->sc_curScreen = 1 - screen;
  screen                  = _current_screen(TheScreen_);
  bitmap = TheScreen_->sc_Bitmaps[screen];
  if(bitmap)
    {
      err = SetVRAMPages(vramIOReq, bitmap->bm_Buffer, 0, TheScreen_->sc_nFrameBufferPages, -1);
      if(err < 0)
        {
          DeleteItem(vramIOReq);
          return 0;
        }
    }

  TheScreen_->sc_curScreen = 1 - screen;
  screen                  = _current_screen(TheScreen_);
  if(TheScreen_->sc_Screens[screen])
    DisplayScreen(TheScreen_->sc_Screens[screen], 0);
  if(!InitBackPic(TheScreen_, vramIOReq))
    {
      DeleteItem(vramIOReq);
      return 0;
    }
  TheScreen_->sc_curScreen = 0;
  err = DeleteItem(vramIOReq);
  return 1;
}


int32
DisplayBarnDoorOpen(ScreenContext *sc_,
                    Item           vramIOReq_,
                    CCB           *underCel_,
                    CCB           *doorCel_)
{
  Item vblIOReq;
  Point quad[4];
  Bitmap *bitmap;
  int32 screen;
  int32 edge;
  int32 result;
  int32 waitResult;

  if(!sc_)
    return -1;

  result   = 1;
  vblIOReq = GetVBLIOReq();
  if(vblIOReq < 0)
    return -1;

  for(edge = 160; edge >= 0; edge -= 10)
    {
      sc_->sc_curScreen = 1 - _current_screen(sc_);
      screen           = _current_screen(sc_);
      bitmap           = sc_->sc_Bitmaps[screen];
      if(!bitmap || CopyVRAMPages(vramIOReq_, bitmap->bm_Buffer, gBackPic,
                                  sc_->sc_nFrameBufferPages,
                                  (uint32) - 1) != 0)
        {
          result = -1;
          goto cleanup;
        }

      if(doorCel_)
        {
          _set_quad(quad, edge, 0, BULLETHOLE_SCREEN_W - edge, BULLETHOLE_SCREEN_H);
          MapCel(doorCel_, quad);
        }
      if(underCel_)
        DrawScreenCels(sc_->sc_Screens[screen], underCel_);
      if(doorCel_)
        DrawScreenCels(sc_->sc_Screens[screen], doorCel_);
      DisplayScreen(sc_->sc_Screens[screen], 0);
      PDWTSceneControlPresent(screen);
      waitResult = PDWTSceneControlWaitFields(vblIOReq, 1);
      if(waitResult != PDWT_SCENE_CONTROL_CONTINUE)
        {
          result = waitResult;
          goto cleanup;
        }
    }

cleanup:
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }
  return result;
}


int32
DisplayCenterMerge(ScreenContext *sc_,
                   Item           vramIOReq_,
                   CCB           *mergeCel_,
                   CCB           *underCel_)
{
  Item vblIOReq;
  Point quad[4];
  Bitmap *bitmap;
  int32 screen;
  int32 spread;
  int32 halfHeight;
  int32 result;
  int32 waitResult;

  if(!sc_)
    return -1;

  result   = 1;
  vblIOReq = GetVBLIOReq();
  if(vblIOReq < 0)
    return -1;

  for(spread = 160; spread >= 0; spread -= 5)
    {
      sc_->sc_curScreen = 1 - _current_screen(sc_);
      screen           = _current_screen(sc_);
      bitmap           = sc_->sc_Bitmaps[screen];
      if(!bitmap || CopyVRAMPages(vramIOReq_, bitmap->bm_Buffer, gBackPic,
                                  sc_->sc_nFrameBufferPages,
                                  (uint32) - 1) != 0)
        {
          result = -1;
          goto cleanup;
        }

      if(mergeCel_)
        {
          halfHeight = (spread * 3) / 4;
          _set_quad(quad, 160 - spread, 120 - halfHeight, 160 + spread, 120 + halfHeight);
          MapCel(mergeCel_, quad);
        }
      if(underCel_)
        DrawScreenCels(sc_->sc_Screens[screen], underCel_);
      if(mergeCel_)
        DrawScreenCels(sc_->sc_Screens[screen], mergeCel_);
      DisplayScreen(sc_->sc_Screens[screen], 0);
      PDWTSceneControlPresent(screen);
      waitResult = PDWTSceneControlWaitFields(vblIOReq, 1);
      if(waitResult != PDWT_SCENE_CONTROL_CONTINUE)
        {
          result = waitResult;
          goto cleanup;
        }
    }

cleanup:
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }
  return result;
}


