int32
bullethole(CCB           *backCel_,
           int32          remaining_,
           Item           vblIOReq_,
           Item           vramIOReq_,
           ScreenContext *sc_)
{
  CCB    *holeCel;
  Bitmap *bitmap;
  Item bitmapItem;
  TagArg bitmapTags[4];
  Item screenItem;
  ubyte  *tempBuffer;
  int32 frame;
  int32 delay;
  int32 waitResult;
  int32 result;
  int32 curScreen;
  int32 dx;
  int32 dy;
  int32 dir;
  int32 phase;
  uint32 randomValue;

  if(!backCel_ || !sc_)
    return -1;

  tempBuffer = (ubyte *)AllocMem(BULLETHOLE_TEMP_SIZE, BULLETHOLE_TEMP_MEMTYPE);
  if(!tempBuffer)
    return -1;

  bitmapTags[0].ta_Tag = BULLETHOLE_BMTAG_WIDTH;
  bitmapTags[0].ta_Arg = (void *)BULLETHOLE_SCREEN_W;
  bitmapTags[1].ta_Tag = BULLETHOLE_BMTAG_HEIGHT;
  bitmapTags[1].ta_Arg = (void *)BULLETHOLE_SCREEN_H;
  bitmapTags[2].ta_Tag = BULLETHOLE_BMTAG_BUFFER;
  bitmapTags[2].ta_Arg = tempBuffer;
  bitmapTags[3].ta_Tag = 0;
  bitmapTags[3].ta_Arg = 0;

  bitmapItem = CreateItem(BULLETHOLE_BITMAP_NODE, bitmapTags);
  if(bitmapItem < 0)
    {
      FreeMem(tempBuffer, BULLETHOLE_TEMP_SIZE);
      return -1;
    }
  bitmap = (Bitmap *)LookupItem(bitmapItem);
  if(!bitmap)
    {
      if(bitmapItem > 0)
        {
          DeleteItem(bitmapItem);
        }
      FreeMem(tempBuffer, BULLETHOLE_TEMP_SIZE);
      return -1;
    }

  holeCel = LoadCel(BULLETHOLE_CEL_PATH, MEMTYPE_CEL);
  if(!holeCel)
    {
      if(bitmapItem > 0)
        {
          DeleteItem(bitmapItem);
        }
      FreeMem(tempBuffer, BULLETHOLE_TEMP_SIZE);
      return -1;
    }

  randomValue       = (uint32)rand();
  holeCel->ccb_XPos = (Coord)((randomValue >> 16) * BULLETHOLE_RANDOM_X_SCALE);
  randomValue       = (uint32)rand();
  holeCel->ccb_YPos = (Coord)((randomValue >> 16) * BULLETHOLE_RANDOM_Y_SCALE);

  backCel_->ccb_NextPtr = holeCel;
  backCel_->ccb_Flags &= ~CCB_LAST;
  holeCel->ccb_NextPtr = (CCB *)0;
  holeCel->ccb_Flags |= CCB_LAST;

  curScreen = sc_->sc_curScreen;
  if(curScreen < 0 || curScreen >= 6)
    curScreen = 0;
  screenItem = sc_->sc_Screens[curScreen];
  if(screenItem)
    DrawScreenCels(screenItem, backCel_);
  if(screenItem)
    {
      DisplayScreen(screenItem, 0);
      PDWTSceneControlPresent(curScreen);
    }
  if(bitmapItem)
    DrawCels(bitmapItem, backCel_);

  frame = 0;
  dx    = 0;
  dy    = 0;
  result = 1;
  while(remaining_ > 0)
    {
      frame++;
      curScreen = sc_->sc_curScreen;
      if(curScreen < 0 || curScreen >= 6)
        curScreen = 0;

      screenItem = sc_->sc_Screens[curScreen];
      if(bitmap)
        {
          waitResult = CopyBackPic(sc_, bitmap, vramIOReq_);
          if(waitResult < 0)
            {
              result = waitResult;
              break;
            }
        }

      backCel_->ccb_Flags     = BULLETHOLE_BG_FLAGS;
      backCel_->ccb_Width     = BULLETHOLE_SCREEN_W;
      backCel_->ccb_Height    = BULLETHOLE_SCREEN_H;
      backCel_->ccb_XPos      = 0;
      backCel_->ccb_YPos      = 0;
      backCel_->ccb_HDX       = 0x00100000L;
      backCel_->ccb_HDY       = 0;
      backCel_->ccb_VDX       = 0;
      backCel_->ccb_VDY       = 0x00010000L;
      backCel_->ccb_HDDX      = 0;
      backCel_->ccb_HDDY      = 0;
      backCel_->ccb_PIXC      = BULLETHOLE_PIXC;
      backCel_->ccb_PRE0      = ((BULLETHOLE_SCREEN_H - 1) << 6) | 0x16;
      backCel_->ccb_PRE1      = (BULLETHOLE_SCREEN_W - 1) | 0x013C0000UL | 0x00020800UL;
      backCel_->ccb_SourcePtr = bitmap ? (CelData *)bitmap->bm_Buffer : (CelData *)0;

      delay = 0;
      phase = frame % 5;
      if(phase == 0)
        {
          randomValue       = (uint32)rand();
          holeCel->ccb_XPos = (Coord)((randomValue >> 16) * BULLETHOLE_RANDOM_X_SCALE);
          randomValue       = (uint32)rand();
          holeCel->ccb_YPos = (Coord)((randomValue >> 16) * BULLETHOLE_RANDOM_Y_SCALE);
          delay             = 8;
        }
      else if(phase == 1)
        {
          dir = (int32)((uint32)rand() & 7UL);
          switch(dir)
            {
            case 0:
              dx = 0x000C0000L;
              dy = 0x00090000L;
              break;
            case 1:
              dx = 0x00090000L;
              dy = 0x000C0000L;
              break;
            case 2:
              dx = -0x000C0000L;
              dy = 0x00090000L;
              break;
            case 3:
              dx = -0x00090000L;
              dy = 0x000C0000L;
              break;
            case 4:
              dx = -0x000C0000L;
              dy = -0x00090000L;
              break;
            case 5:
              dx = -0x00090000L;
              dy = -0x000C0000L;
              break;
            case 6:
              dx = 0x000C0000L;
              dy = -0x00090000L;
              break;
            default:
              dx = 0x00090000L;
              dy = -0x000C0000L;
              break;
            }
          holeCel->ccb_XPos += dx;
          holeCel->ccb_YPos += dy;
          delay = 3;
        }
      else
        {
          holeCel->ccb_XPos += dx;
          holeCel->ccb_YPos += dy;
          delay = 3;
        }

      if(screenItem)
        DrawScreenCels(screenItem, backCel_);
      if(screenItem)
        {
          DisplayScreen(screenItem, 0);
          PDWTSceneControlPresent(curScreen);
        }
      if(bitmapItem)
        DrawCels(bitmapItem, backCel_);
      if(delay > remaining_)
        delay = remaining_;
      waitResult = PDWTSceneControlWaitFields(vblIOReq_, delay);
      if(waitResult != PDWT_SCENE_CONTROL_CONTINUE)
        {
          result = waitResult;
          break;
        }
      remaining_ -= delay;
    }

  backCel_->ccb_NextPtr = (CCB *)0;
  backCel_->ccb_Flags |= CCB_LAST;
  UnloadCel(holeCel);
  FreeMem(tempBuffer, BULLETHOLE_TEMP_SIZE);
  if(bitmapItem > 0)
    {
      DeleteItem(bitmapItem);
    }
  return result;
}


int32
decSpeech(DecDataPtr choice_)
{
  uchar name[32];
  SoundFilePlayer *player;
  int32 signalIn;
  int32 signalNeeded;
  int32 err;
  int32 closeErr;

  if(!choice_)
    return -1;

  sprintf((char *)name, "$boot/tuntest/dec/%s", choice_->name);

  player = OpenSoundFile((char *)name, 2, 0x8000);
  if(!player)
    return -1;

  err = StartSoundFile(player, 0x4000);
  if(err < 0)
    goto cleanup;

  signalIn     = 0;
  signalNeeded = 0;
  do
    {
      if(signalNeeded != 0)
        {
          signalIn = WaitSignal((uint32)signalNeeded);
        }
      err = ServiceSoundFile(player, signalIn, &signalNeeded);
      if(err < 0)
        {
          goto cleanup;
        }
    } while(signalNeeded != 0);

cleanup:
  closeErr = CloseSoundFile(player);
  if(err < 0)
    return -1;
  if(closeErr < 0)
    return -1;
  return 0;
}


PicDataPtr
ReadPictureData(uint8 *name_,
                int32 *count_)
{
  uchar sceneNum[3];
  int32 scene;

  sceneNum[0] = name_[3];
  sceneNum[1] = name_[4];
  sceneNum[2] = 0;
  scene       = atoi((char *)sceneNum);

  switch(scene)
    {
    case 15:
      *count_ = 17;
      return dsc15;
    case 16:
      *count_ = 9;
      return dsc16;
    case 17:
      *count_ = 14;
      return dsc17;
    case 18:
      *count_ = 20;
      return dsc18;
    case 20:
      *count_ = 12;
      return dsc20;
    case 21:
      *count_ = 22;
      return dsc21;
    case 22:
      *count_ = 33;
      if(name_[0] == 'd')
        return dsc22;
      return ssc22;
    case 23:
      *count_ = 29;
      return dsc23;
    case 24:
      *count_ = 50;
      return dsc24;
    case 25:
      *count_ = 45;
      return dsc25;
    case 26:
      *count_ = 35;
      return dsc26;
    case 27:
      *count_ = 14;
      return dsc27;
    case 28:
      *count_ = 15;
      return dsc28;
    case 29:
      *count_ = 5;
      return dsc29;
    case 30:
      *count_ = 21;
      return dsc30;
    case 31:
      *count_ = 17;
      return dsc31;
    case 32:
      *count_ = 23;
      return dsc32;
    }
  *count_ = 0;
  return (PicDataPtr)0;
}


static
uint32
_picture_table_fields(PicDataPtr data_,
                      int32      count_)
{
  uint32 total;
  int32 i;

  total = 0;
  for(i = 0; i < count_; i++)
    {
      total += (uint32)data_[i].time;
    }
  return total;
}


int32
showpicture(ScreenContext *TheScreen_,
            uint8         *Nscene_)
{
  uchar dataName[50];
  uchar path[50];
  DecisionAudio sceneAudio;
  PDWTSceneControl sceneControl;
  PDWTSceneClock sceneClock;
  PicDataPtr data;
  Bitmap            *bitmap;
  Item vramIOReq;
  Item vblIOReq;
  int32 count;
  int32 i;
  int32 screen;
  int32 scheduleFields;
  int32 active;
  int32 sc25Scene;
  int32 eventOpen;
  int32 eventResult;
  int32 mainSceneLoaded;
  int32 audioComplete;
  int32 controlOpen;
  int32 audioResult;
  int32 sceneResult;
  int32 result;

  if(!TheScreen_ || !Nscene_)
    return -1;

  DecisionAudioInit(&sceneAudio);
  PDWTSceneControlInit(&sceneControl);
  vramIOReq       = 0;
  vblIOReq        = 0;
  eventOpen       = 0;
  mainSceneLoaded = 0;
  audioComplete   = 0;
  controlOpen     = 0;
  result          = -1;

  vramIOReq = GetVRAMIOReq();
  if(vramIOReq < 0)
    goto cleanup;
  vblIOReq = GetVBLIOReq();
  if(vblIOReq < 0)
    goto cleanup;
  count = 0;

  if(strcmp((char *)Nscene_, "sc22") == 0 && secretpass)
    {
      sprintf((char *)dataName, "s%s", Nscene_);
    }
  else
    {
      sprintf((char *)dataName, "d%s", Nscene_);
    }

  data = ReadPictureData(dataName, &count);
  if(!data)
    goto cleanup;

  eventResult = InitEventUtility(1, 0, 1);
  if(eventResult != 0)
    {
      result = eventResult < 0 ? eventResult : -1;
      goto cleanup;
    }
  eventOpen = 1;

  sprintf((char *)dataName, "$boot/tuntest/%s/%s.aiff", Nscene_, Nscene_);
  audioResult = DecisionAudioStartWithBuffers(
    &sceneAudio,
    dataName,
    STORY_AUDIO_BUFFER_COUNT,
    STORY_AUDIO_BUFFER_SIZE,
    STORY_AUDIO_AMPLITUDE);
  if(audioResult < 0)
    {
      result = audioResult;
      goto cleanup;
    }
  PDWTSceneClockStart(&sceneClock, Nscene_, _picture_table_fields(data, count));

  TheScreen_->sc_curScreen = 0;
  active    = 1;
  sc25Scene = strcmp((char *)Nscene_, "sc25") == 0;
  sceneResult = PDWTSceneControlBegin(
    &sceneControl,
    TheScreen_,
    vramIOReq,
    vblIOReq,
    &sceneAudio,
    &sceneClock);
  if(sceneResult < 0)
    {
      result = sceneResult;
      goto cleanup;
    }
  controlOpen = 1;
  if(sceneResult == PDWT_SCENE_CONTROL_STEP_BACK)
    {
      stepback = 1;
      active   = 0;
    }
  else if(sceneResult == PDWT_SCENE_CONTROL_SKIP)
    {
      active = 0;
    }

  for(i = 0; i < count && active; i++)
    {
      sprintf((char *)path, "$boot/tuntest/%s/%s", Nscene_, data[i].name);
      MainScene = LoadCel((char *)path, MEMTYPE_CEL);
      if(!MainScene)
        goto cleanup;
      mainSceneLoaded        = 1;
      MainScene->ccb_NextPtr = (CCB *)0;
      MainScene->ccb_Flags |= CCB_LAST;
      _center_cel(MainScene);

      screen = _current_screen(TheScreen_);
      bitmap = TheScreen_->sc_Bitmaps[screen];
      if(bitmap)
        {
          sceneResult = CopyBackPic(TheScreen_, bitmap, vramIOReq);
          if(sceneResult < 0)
            {
              result = sceneResult;
              goto cleanup;
            }
        }

      scheduleFields = data[i].time;
      if(sc25Scene && (data[i].time & 1))
        {
          sceneResult = bullethole(MainScene, scheduleFields, vblIOReq, vramIOReq, TheScreen_);
        }
      else if(i == 0)
        {
          sceneResult = DisplayBarnDoorOpen(TheScreen_, vramIOReq, 0, MainScene);
        }
      else
        {
          sceneResult = PDWT_SCENE_CONTROL_CONTINUE;
          if(TheScreen_->sc_Screens[screen])
            {
              DrawScreenCels(TheScreen_->sc_Screens[screen], MainScene);
              DisplayScreen(TheScreen_->sc_Screens[screen], 0);
              PDWTSceneControlPresent(screen);
            }
        }

      if(sceneResult < 0)
        {
          result = sceneResult;
          goto cleanup;
        }
      if(sceneResult == PDWT_SCENE_CONTROL_STEP_BACK)
        {
          stepback = 1;
          active   = 0;
        }
      else if(sceneResult == PDWT_SCENE_CONTROL_SKIP)
        {
          active = 0;
        }

      TheScreen_->sc_curScreen = 1 - _current_screen(TheScreen_);
      if(active)
        {
          sceneResult = PDWTSceneControlWaitClock(&sceneClock, vblIOReq, scheduleFields);
          if(sceneResult < 0)
            {
              result = sceneResult;
              goto cleanup;
            }
          if(sceneResult == PDWT_SCENE_CONTROL_STEP_BACK)
            {
              stepback = 1;
              active   = 0;
            }
          else if(sceneResult == PDWT_SCENE_CONTROL_SKIP)
            {
              active = 0;
            }
        }
      if(active && i == count - 1)
        {
          sceneResult = PDWTSceneControlWaitAudio(&sceneAudio, vblIOReq);
          if(sceneResult < 0)
            {
              result = sceneResult;
              goto cleanup;
            }
          if(sceneResult == PDWT_SCENE_CONTROL_STEP_BACK)
            {
              stepback = 1;
              active   = 0;
            }
          else if(sceneResult == PDWT_SCENE_CONTROL_SKIP)
            {
              active = 0;
            }
          else
            {
              audioComplete = 1;
            }
        }
      if(active && i == count - 1)
        {
          sceneResult = DisplayCenterMerge(TheScreen_, vramIOReq, MainScene, 0);
          if(sceneResult < 0)
            {
              result = sceneResult;
              goto cleanup;
            }
          if(sceneResult == PDWT_SCENE_CONTROL_STEP_BACK)
            {
              stepback = 1;
              active   = 0;
            }
          else if(sceneResult == PDWT_SCENE_CONTROL_SKIP)
            {
              active = 0;
            }
        }
      UnloadCel(MainScene);
      MainScene       = 0;
      mainSceneLoaded = 0;
    }

  if(active && !audioComplete)
    {
      sceneResult = PDWTSceneControlWaitAudio(&sceneAudio, vblIOReq);
      if(sceneResult < 0)
        {
          result = sceneResult;
          goto cleanup;
        }
      if(sceneResult == PDWT_SCENE_CONTROL_STEP_BACK)
        {
          stepback = 1;
          active   = 0;
        }
      else if(sceneResult == PDWT_SCENE_CONTROL_SKIP)
        {
          active = 0;
        }
    }

  PDWTSceneControlEnd(&sceneControl);
  controlOpen = 0;
  screen = _current_screen(TheScreen_);
  bitmap = TheScreen_->sc_Bitmaps[screen];
  if(bitmap)
    {
      sceneResult = CopyBackPic(TheScreen_, bitmap, vramIOReq);
      if(sceneResult < 0)
        {
          result = sceneResult;
          goto cleanup;
        }
    }
  result = 1;

cleanup:
  if(controlOpen)
    {
      PDWTSceneControlEnd(&sceneControl);
    }
  if(mainSceneLoaded && MainScene)
    {
      UnloadCel(MainScene);
      MainScene = 0;
    }
  audioResult = DecisionAudioStop(&sceneAudio);
  if(audioResult < 0 && result >= 0)
    {
      result = audioResult;
    }
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }
  if(vramIOReq > 0)
    {
      DeleteItem(vramIOReq);
    }
  if(eventOpen)
    {
      eventResult = KillEventUtility();
      if(eventResult != 0 && result >= 0)
        {
          result = eventResult < 0 ? eventResult : -1;
        }
    }
  return result;
}


DecDataPtr
ReadDecisionData(uint8 *name_,
                 int32 *count_)
{
  uchar sceneNum[3];
  int32 scene;

  sceneNum[0] = name_[3];
  sceneNum[1] = name_[4];
  sceneNum[2] = 0;
  scene       = atoi((char *)sceneNum);

  switch(scene)
    {
    case 13:
      *count_ = 3;
      return dec13;
    case 16:
      *count_ = 2;
      return dec16;
    case 18:
      *count_ = 2;
      return dec18;
    case 20:
      *count_ = 2;
      return dec20;
    case 22:
      *count_ = 2;
      return dec22;
    case 23:
      *count_ = 2;
      return dec23;
    case 25:
      *count_ = 2;
      return dec25;
    case 26:
      *count_ = 2;
      return dec26;
    case 28:
      *count_ = 2;
      return dec28;
    case 29:
      *count_ = 2;
      return dec29;
    case 30:
      *count_ = 3;
      return dec30;
    case 31:
      *count_ = 2;
      return dec31;
    }
  *count_ = 0;
  return (DecDataPtr)0;
}


static
int32
_draw_decision_screen(ScreenContext *sc_,
                      Item           vramIOReq_,
                      int32          showHelp_)
{
  Bitmap *bitmap;
  int32 result;
  int32 screen;

  sc_->sc_curScreen = 1 - _current_screen(sc_);
  screen           = _current_screen(sc_);
  bitmap           = sc_->sc_Bitmaps[screen];
  if(bitmap)
    {
      result = CopyBackPic(sc_, bitmap, vramIOReq_);
      if(result < 0)
        {
          return result;
        }
    }

  if(showHelp_)
    {
      if(sc_->sc_Screens[screen])
        {
          DrawScreenCels(sc_->sc_Screens[screen], Help);
        }
    }
  else
    {
      if(sc_->sc_Screens[screen])
        {
          DrawScreenCels(sc_->sc_Screens[screen], MainScene);
          DrawScreenCels(sc_->sc_Screens[screen], Choice[0]);
        }
      PutNumXY(sc_, point, 15, 215);
    }
  if(sc_->sc_Screens[screen])
    {
      DisplayScreen(sc_->sc_Screens[screen], 0);
    }

  return 0;
}


int32
makedecision(ScreenContext *sc_,
             uint8         *name_)
{
  DecisionAudio decisionAudio;
  uchar path[50];
  DecDataPtr choices;
  Point quad[4];
  Bitmap             *bitmap;
  Item vramIOReq;
  Item vblIOReq;
  ControlPadEventData cped;
  uint32 padBits;
  uint32 lastPadBits;
  uint32 oldPadBits;
  uint32 input;
  uint32 filteredPad;
  int32 count;
  int32 selected;
  int32 voicedSelection;
  int32 finish;
  int32 showHelp;
  int32 screen;
  int32 i;
  int32 eventOpen;
  int32 loadedChoices;
  int32 audioResult;
  int32 waitResult;
  int32 result;

  DecisionAudioInit(&decisionAudio);
  vramIOReq     = 0;
  vblIOReq      = 0;
  eventOpen     = 0;
  loadedChoices = 0;
  result        = -1;
  selected      = 0;
  Help          = 0;
  MainScene     = 0;
  for(i = 0; i < 3; i++)
    {
      Choice[i] = 0;
    }

  vramIOReq = GetVRAMIOReq();
  if(vramIOReq < 0)
    goto cleanup;
  vblIOReq = GetVBLIOReq();
  if(vblIOReq < 0)
    goto cleanup;

  Help = LoadCel("$boot/tuntest/dec/controlhelp.cel", MEMTYPE_CEL);
  if(!Help)
    goto cleanup;
  Help->ccb_NextPtr = (CCB *)0;
  Help->ccb_Flags |= CCB_LAST;
  _center_cel(Help);

  sprintf((char *)path, "$boot/tuntest/dec/%s.cel", name_);
  MainScene = LoadCel((char *)path, MEMTYPE_CEL);
  if(!MainScene)
    goto cleanup;
  MainScene->ccb_NextPtr = (CCB *)0;
  MainScene->ccb_Flags |= CCB_LAST;
  _center_cel(MainScene);

  count   = 0;
  choices = ReadDecisionData(name_, &count);
  if(!choices || count <= 0)
    goto cleanup;

  if(InitEventUtility(1, 0, 1) != 0)
    goto cleanup;
  eventOpen = 1;

  for(i = 0; i < count; i++)
    {
      Choice[i] = LoadCel("$boot/tuntest/dec/hilite.cel", MEMTYPE_CEL);
      if(!Choice[i])
        goto cleanup;
      loadedChoices++;
      _set_quad(quad, choices[i].x, choices[i].y, choices[i].x + choices[i].w,
                choices[i].y + choices[i].h);
      MapCel(Choice[i], quad);
      Choice[i]->ccb_PIXC = HILITE_PIXC;
    }
  for(i = 1; i < count; i++)
    {
      Choice[i - 1]->ccb_NextPtr = Choice[i];
      Choice[i - 1]->ccb_Flags &= ~CCB_LAST;
    }
  Choice[count - 1]->ccb_NextPtr = (CCB *)0;
  Choice[count - 1]->ccb_Flags |= CCB_LAST;
  Choice[0]->ccb_PIXC = HILITE_SELECTED_PIXC;

  selected        = 0;
  voicedSelection = -1;
  finish          = 1;
  showHelp        = 0;
  lastPadBits     = 0;
  input           = 0;

  result = _draw_decision_screen(sc_, vramIOReq, showHelp);
  if(result < 0)
    {
      goto cleanup;
    }
  sprintf((char *)path, DECISION_SPEECH_PATH_FORMAT, choices[selected].name);
  audioResult = DecisionAudioStart(&decisionAudio, path, DECISION_SPEECH_BUFFER_SIZE,
                                   DECISION_SPEECH_AMPLITUDE);
  if(audioResult < 0)
    goto cleanup;
  voicedSelection = selected;

  while(finish)
    {

      waitResult = WaitVBL(vblIOReq, 1);
      if(waitResult < 0)
        goto cleanup;
      audioResult = DecisionAudioService(&decisionAudio);
      if(audioResult < 0)
        goto cleanup;

      cped.cped_ButtonBits = 0;
      if(GetControlPad(1, 0, &cped) < 0)
        goto cleanup;
      padBits    = cped.cped_ButtonBits;
      oldPadBits = lastPadBits;
      if((padBits ^ lastPadBits) != 0)
        {
          input = padBits;
        }
      else
        {
          filteredPad = padBits & ~0x07000000UL;
          filteredPad &= ~0x00DF0000UL;
          filteredPad &= ~0x0000FF00UL;
          filteredPad &= ~0x000000FFUL;
          if(filteredPad == 0)
            input = 0;
        }

      if(input == RAW_PAD_SELECT)
        {
          finish = 0;
        }
      else if(input == RAW_PAD_UP || input == RAW_PAD_LEFT)
        {
          if(oldPadBits != RAW_PAD_LEFT && oldPadBits != RAW_PAD_UP)
            {
              audioResult = DecisionAudioStop(&decisionAudio);
              if(audioResult < 0)
                goto cleanup;
              Choice[selected]->ccb_PIXC = HILITE_PIXC;
              selected                   = (selected + count - 1) % count;
              Choice[selected]->ccb_PIXC = HILITE_SELECTED_PIXC;
              voicedSelection = -1;
            }
        }
      else if(input == RAW_PAD_DOWN || input == RAW_PAD_RIGHT)
        {
          if(oldPadBits != RAW_PAD_RIGHT && oldPadBits != RAW_PAD_DOWN)
            {
              audioResult = DecisionAudioStop(&decisionAudio);
              if(audioResult < 0)
                goto cleanup;
              Choice[selected]->ccb_PIXC = HILITE_PIXC;
              selected                   = (selected + 1) % count;
              Choice[selected]->ccb_PIXC = HILITE_SELECTED_PIXC;
              voicedSelection = -1;
            }
        }
      else if(input == RAW_PAD_STEPBACK)
        {
          finish   = 0;
          stepback = 1;
        }
      else if(input == RAW_PAD_HELP)
        {
          showHelp = 1;
        }
      else
        {
          showHelp = 0;
        }
      lastPadBits = padBits;

      if(!finish)
        break;

      result = _draw_decision_screen(sc_, vramIOReq, showHelp);
      if(result < 0)
        {
          goto cleanup;
        }
      if(voicedSelection != selected)
        {
          sprintf((char *)path, DECISION_SPEECH_PATH_FORMAT, choices[selected].name);
          audioResult =
            DecisionAudioStart(&decisionAudio, path, DECISION_SPEECH_BUFFER_SIZE,
                               DECISION_SPEECH_AMPLITUDE);
          if(audioResult < 0)
            goto cleanup;
          voicedSelection = selected;
        }
    }

  screen = _current_screen(sc_);
  bitmap = sc_->sc_Bitmaps[screen];
  if(bitmap)
    {
      result = CopyBackPic(sc_, bitmap, vramIOReq);
      if(result < 0)
        {
          goto cleanup;
        }
    }
  result = selected + 1;

cleanup:
  audioResult = DecisionAudioStop(&decisionAudio);
  if(audioResult < 0)
    {
      result = -1;
    }
  if(Help)
    {
      UnloadCel(Help);
      Help = 0;
    }
  if(MainScene)
    {
      UnloadCel(MainScene);
      MainScene = 0;
    }
  for(i = 0; i < loadedChoices; i++)
    {
      if(Choice[i])
        {
          UnloadCel(Choice[i]);
          Choice[i] = 0;
        }
    }
  if(eventOpen && KillEventUtility() != 0)
    {
      result = -1;
    }
  if(vramIOReq > 0)
    {
      DeleteItem(vramIOReq);
    }
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }
  return result;
}


