int32
ShowCase(ScreenContext *TheScreen_,
         uint8         *Nscene_)
{
  int32 finish;
  int32 transition;

  if(!Nscene_)
    return -1;

  finish = 0;
  for(transition = 0; transition < SHOWCASE_MAX_TRANSITIONS; transition++)
    {
      showOption(Nscene_, &finish);
      stepback = 0;

      if(_str_equal(Nscene_, "sc13"))
        return 25;

      if(Nscene_[0] == 's')
        {
          finish = showpicture(TheScreen_, Nscene_);
          if(finish < 0)
            return -1;
        }
      if(Nscene_[0] == 'd')
        {
          finish = makedecision(TheScreen_, Nscene_);
          if(finish < 0)
            return -1;
        }
      if(_str_equal(Nscene_, "end"))
        return 100;
      if(Nscene_[0] != 's' && Nscene_[0] != 'd')
        return -1;
    }

  return -1;
}


int32
DEC13(void)
{
  uchar scene[10];
  Item fileItem;
  int32 result;

  if(!InitPicture(&gScreenContext))
    {
      return -1;
    }

  _copy_name(RootName, (const uchar *)"/cd-rom", 15);
  fileItem = OpenDiskFile("/cd-rom/tuntest/dec/dec13.data");
  if(fileItem >= 0)
    {
      CloseDiskFile(fileItem);
    }
  else
    {
      _copy_name(RootName, (const uchar *)"/remote", 15);
    }

  _copy_name(scene, (const uchar *)"dec13", 10);
  stepback = 0;
  result = ShowCase(&gScreenContext, scene);

  if(gBackPic)
    {
      FreeMem(gBackPic, _back_pic_size(&gScreenContext));
      gBackPic = 0;
    }
  if(startover)
    {
      startover = 0;
      result    = 50;
    }
  return result;
}
